export interface CodexDiscoveredModel {
  model: string;
  displayName: string;
  isDefault: boolean;
}

const DEFAULT_TIMEOUT_MS = 8_000;
const MAX_PAGES = 100;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function nonemptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

/**
 * Read the installed Codex CLI's available models without starting a thread or
 * turn. The deadline covers initialization and every page together. Callers own
 * caching and fallback policy; a valid empty catalog is distinct from failure.

const models = new Map<string, CodexDiscoveredModel>();
const cursors = new Set<string>();
let cursor: string | undefined;
for (let page = 0; page < MAX_PAGES; page++) {
  const result = await client.request(
    "model/list",
    { includeHidden: false, limit: 100, ...(cursor ? { cursor } : {}) },

  if (!isRecord(result) || !Array.isArray(result.data)) {
    throw new Error("Invalid Codex model/list response");
  }
  for (const entry of result.data) {
    if (
      !isRecord(entry) ||
      !nonemptyString(entry.model) ||
      !nonemptyString(entry.displayName) ||
      (entry.isDefault !== undefined && typeof entry.isDefault !== "boolean") ||
      (entry.hidden !== undefined && typeof entry.hidden !== "boolean")
    ) {
      throw new Error("Invalid Codex model/list entry");
    }
    if (entry.hidden === true || models.has(entry.model)) continue;
    models.set(entry.model, {
      model: entry.model,
      displayName: entry.displayName,
      isDefault: entry.isDefault === true,
    });
  }

  if (result.nextCursor === null || result.nextCursor === undefined) {
    return [...models.values()];
  }
  if (!nonemptyString(result.nextCursor) || cursors.has(result.nextCursor)) {
    throw new Error("Invalid Codex model/list pagination cursor");
  }
  cursor = result.nextCursor;
  cursors.add(cursor);
}
throw new Error("Codex model/list exceeded the pagination limit");

interface ModelCache {
  entries: ExternalRuntimeModelEntry[];
  expiresAt: number;
  pending?: Promise<ExternalRuntimeModelEntry[]>;
}

interface ExternalRuntimeModelServiceOptions {
  isEnabled: () => boolean;
  probe?: typeof probeExternalRuntimes;
  discoverCodex?: typeof discoverCodexModels;
  now?: () => number;
}

/** One shared catalog cache across windows; discovery never opens an agent turn. */
export class ExternalRuntimeModelService {
  private readonly cache = new Map<string, ModelCache>();

  constructor(private readonly options: ExternalRuntimeModelServiceOptions) {}

  async list(): Promise<ExternalRuntimeModelEntry[]> {
    if (!this.options.isEnabled()) {
      this.cache.clear();
      return [];
    }

  const available = probed.filter((runtime) => runtime.path !== null);
  const codex = available.find((runtime) => runtime.kind === "codex");
  const otherEntries = externalRuntimeModelEntries(
    available.filter((runtime) => runtime.kind !== "codex").map((runtime) => runtime.kind),
  );
  if (!codex?.path) return otherEntries;

  const codexEntries = await this.codexEntries(codex.path);
  // The feature can be disabled while a discovery request is in flight.
  return this.options.isEnabled() ? [...codexEntries, ...otherEntries] : [];
}

let cached = this.cache.get(command);
if (!cached) {
  cached = { entries: externalRuntimeModelEntries(["codex"]), expiresAt: 0 };
  this.cache.set(command, cached);
}

const entry = cached;
entry.pending = Promise.resolve().then(async () => {
  try {
    const models = await (this.options.discoverCodex ?? discoverCodexModels)({
      command,

  entry.entries = [...models]
    .sort((a, b) => Number(b.isDefault) - Number(a.isDefault))
    .map(({ model, displayName }) => ({
      key: externalRuntimeModelKey("codex", model),
      label: `Codex · ${displayName}`,
      provider: "codex",
      kind: "codex",
      maxContextTokens: EXTERNAL_RUNTIME_FALLBACK_CONTEXT_TOKENS,
    }));
} catch (error) {
  // Keep the last successful response, or the bundled fallback on first
  // launch. Cache failures too so focus events cannot spawn a retry loop.
  dlog("external-runtime", "models.discovery_failed", {
    error: error instanceof Error ? error.name : "unknown",
  });

    return entry.entries;
  });
  return entry.pending;
}

/** Runtime kinds that can back a model entry. Mirrors ExternalRuntimeKind. */
export type ExternalRuntimeModelKind = "codex" | "claude-code";

/** The `provider` value carried on a ModelOption for these entries. */
export const EXTERNAL_RUNTIME_PROVIDERS: Readonly<Record<ExternalRuntimeModelKind, string>> =
  Object.freeze({
    codex: "codex",
    "claude-code": "claude-code",
  });

const PREFIXES: readonly ExternalRuntimeModelKind[] = ["codex", "claude-code"];

/**
 * Runtime model lists do not always include context-window metadata. Keep
 * the context ring useful until a runtime/model reports a real window; an
 * explicit per-model value below always wins over this fallback.
 */
export const EXTERNAL_RUNTIME_FALLBACK_CONTEXT_TOKENS = 1_000_000;

export interface ParsedExternalRuntimeModel {
  kind: ExternalRuntimeModelKind;
  /** The runtime-specific model id, or undefined to let the runtime decide. */
  model?: string;
}

/** Build the model key for a runtime + model id. Inverse of the parser. */
export function externalRuntimeModelKey(kind: ExternalRuntimeModelKind, model: string): string {
  return `${kind}/${model}`;
}

/**
 * Bundled model choices for runtimes without discovery, or when discovery fails.
 *
 * Desktop prefers Codex's `model/list` response, so new models do not require
 * an app release. These entries keep the picker usable with older CLIs or when
 * discovery is unavailable. Claude Code currently uses the bundled aliases.
 */
export const EXTERNAL_RUNTIME_MODELS: Readonly<
  Record<
    ExternalRuntimeModelKind,
    readonly { model: string; label: string; maxContextTokens?: number }[]
  >
> = Object.freeze({
  codex: Object.freeze([
    { model: "gpt-6-astra", label: "Codex · GPT-6 Astra" },
    { model: "gpt-5.6-sol", label: "Codex · GPT-5.6 Sol" },
    { model: "gpt-5.6-terra", label: "Codex · GPT-5.6 Terra" },
    { model: "gpt-5.6-luna", label: "Codex · GPT-5.6 Luna" },
  ]),
  "claude-code": Object.freeze([
    { model: "opus", label: "Claude Code · Opus" },
    { model: "sonnet", label: "Claude Code · Sonnet" },
    { model: "haiku", label: "Claude Code · Haiku" },
  ]),
});

export interface ExternalRuntimeModelEntry {
  key: string;
  label: string;
  provider: string;
  kind: ExternalRuntimeModelKind;
  maxContextTokens: number;
}

/**
 * Flatten the catalog into pickable entries for the runtimes that are actually
 * installed.
 *
 * `available` gates the list because an entry the machine cannot run is worse
 * than no entry: the user picks it, sends a message, and gets a spawn failure.
 * Detection lives in main (it needs PATH resolution); the renderer only renders
 * what it is told is available.
 */
export function externalRuntimeModelEntries(
  available: readonly ExternalRuntimeModelKind[],
): ExternalRuntimeModelEntry[] {
  const entries: ExternalRuntimeModelEntry[] = [];
  for (const kind of PREFIXES) {
    if (!available.includes(kind)) continue;
    for (const { model, label, maxContextTokens } of EXTERNAL_RUNTIME_MODELS[kind]) {
      entries.push({
        key: externalRuntimeModelKey(kind, model),
        label,
        provider: EXTERNAL_RUNTIME_PROVIDERS[kind],
        kind,
        maxContextTokens: maxContextTokens ?? EXTERNAL_RUNTIME_FALLBACK_CONTEXT_TOKENS,
      });
    }
  }
  return entries;
}

import type { ExternalRuntimeModelEntry } from "../../shared/external-runtime-models";

const REFRESH_INTERVAL_MS = 5 * 60 * 1_000;

/** Keep runtime choices current without delaying configured/native model loading. */
export function useExternalRuntimeModels(
  enabled: boolean,
  settingsRevision: number,
): ExternalRuntimeModelEntry[] {
  const [models, setModels] = useState<ExternalRuntimeModelEntry[]>([]);
  const inFlight = useRef<Promise<ExternalRuntimeModelEntry[]> | null>(null);

  useEffect(() => {
    if (!enabled) {
      setModels([]);
      return;
    }

const refresh = (): Promise<void> => {
  if (cancelled) return Promise.resolve();
  if (refreshing) return refreshing;
  refreshing = (async () => {
    try {
      // A settings change can invalidate a request while IPC is still running.
      // Wait for it before issuing the new query, and never apply its old result.
      if (inFlight.current) await inFlight.current.catch(() => undefined);
      if (cancelled) return;
      const request = window.codeshell.externalRuntime.models();
      inFlight.current = request;
      try {
        const entries = await request;
        if (!cancelled) setModels(entries);
      } finally {
        if (inFlight.current === request) inFlight.current = null;
      }
    } catch {
      // Preserve the last usable list if the bridge is temporarily unavailable.
    }

  }, [enabled, settingsRevision]);

  return enabled ? models : [];
}

const externalRuntimeModels = useExternalRuntimeModels(
  sessionUiAuthority.configurationAvailable,
  settingsRevision,
);

const modelOptions = useMemo<ModelOption[]>(
  () => [...configuredModelOptions, ...externalRuntimeModels],
  [configuredModelOptions, externalRuntimeModels],
);

const externalRuntimeModelService = new ExternalRuntimeModelService({
  isEnabled: () => externalRuntimeService?.isEnabled() ?? false,
});
ipcMain.handle("externalRuntime:models", () => externalRuntimeModelService.list());

// Picked from the ordinary model dropdown as `codex/gpt-5.6-sol` etc. The
// renderer never learns there is a separate backend beyond routing a send.
externalRuntime: {

describe("discoverCodexModels", () => {
  test("handshakes, follows pagination, filters hidden models and deduplicates in server order", async () => {
    const first = { model: "gpt-6-astra", displayName: "GPT-6-Astra", isDefault: true };
    const second = { model: "gpt-5.6-sol", displayName: "GPT-5.6-Sol", isDefault: false };
    const server = fakeServer(`
      if (m.method === "initialize") send({ id: m.id, result: {} });
      if (m.method === "model/list") send({ id: m.id, result: m.params.cursor
        ? { data: [${JSON.stringify(first)}, ${JSON.stringify(second)}], nextCursor: null }
        : { data: [${JSON.stringify(first)}, {
          model: "hidden-model", displayName: "Hidden", isDefault: false, hidden: true,
        }], nextCursor: "page-2" }
      });
    `);

    expect(await discoverCodexModels(server.options)).toEqual([first, second]);
    const requests = server.requests();
    expect(requests.map((request) => request.method)).toEqual([
      "initialize",
      "initialized",
      "model/list",
      "model/list",
    ]);
    expect(requests[2].params).toEqual({ includeHidden: false, limit: 100 });
    expect(requests[3].params).toEqual({ includeHidden: false, limit: 100, cursor: "page-2" });
    expect(server.closed()).toBe(true);
  });

test("returns a valid empty catalog without substituting a fallback", async () => {
  const server = respondWith({ data: [], nextCursor: null });
  expect(await discoverCodexModels(server.options)).toEqual([]);
  expect(server.closed()).toBe(true);
});
